def transforms(I, sr, sc, rf, cf, ro=None, co=None):
    # sr=sc=scale; rf=flip vertical, cf=flip horizontal (of scaled object); ro,co = offset added after flipping
    H,W=I.shape
    ys,xs=np.where(I==objc)
    cy,cx=int(round(np.median(ys))) , int(round(np.median(xs)))  # anchor... actually use bbox center
    # instead anchor = centroid of object
    cnty=(ys.sum()); cntx=(xs.sum())
    cy,cx=int(round(cnty/len(ys))), int(round(cntx/len(xs)))
    pts=[]
    for r,c in zip(ys,xs):
        rr=(r-cy)*sr
        cc=(c-cx)*sc
        if rf: rr=-rr
        if cf: cc=-cc
        rr+=ro; cc+=co
        if 0<=rr<H and 0<=cc<W: pts.append((int(rr),int(cc)))
    return set(pts)

