G=load()

def solve(i):
    I=np.array(G[f'Demo pair {i} input']); O=np.array(G[f'Demo pair {i} output'])
    cnt=Counter(I.flatten()); bgc=max(cnt,key=cnt.get); nl={c for c,n in cnt.items() if c!=bgc}
    linec=max(nl,key=lambda c:cnt[c]); objc=min(nl,key=lambda c:cnt[c])
    rs=np.array([int((I[r]==linec).sum()) for r in range(I.shape[0])]); cs=np.array([int((I[:,c]==linec).sum()) for c in range(I.shape[1])])
    mr=int(rs.argmax()); mc=int(cs.argmax())
    ys,xs=np.where(I==objc)
    M=(I==objc)[ys.min():ys.max()+1, xs.min():xs.max()+1]
    Ho,Wo=I.shape-1,I.shape[1]-1
    oset={(r,c) for r in range(Ho) for c in range(Wo) if O[r,c]==linec}
    vars_=[M,M[::-1,:],M[:,::-1],M[::-1,::-1]]
    names_=['id','fliph','flipud','rot180']
    sols=[]
    for sizes in range(1,5):
        for comb in __import__('itertools').combinations(range(4),sizes):
            if not all(vars_[j]!=vars_[k] for j,k in zip(comb,comb[1:])): continue
            best=None
            def dfs(k,offs,covered,pset):
                nonlocal best
                if covered>=len(oset) and (not pset or covered==len(oset)) and pset<=oset:
                    score=-len(pset-oset)-covered
                    if best is None or score>best[0]: best=(score,offs[:],pset)
                if k==len(comb): return
                for dr in range(-Ho-2,Ho+3):
                    for dc in range(-Wo-2,Wo+3):
                        V=vars_[comb[k]]
                        h_,w_=V.shape
                        rr0,rr1=dr,dr+h_-1; cc0,cc1=dc,dc+w_-1
                        if not (0<=rr0 and rr1<H and 0<=cc0 and cc1<W): continue
                        pset.update(((r,c) for r in range(rr0,rr1+1) for c in range(cc0,cc1+1) if V[r-rr0,c-cc0]))
                        dfs(k+1,offs+[dr,dc],covered+len(pset),pset)
                        pset.difference_update(((r,c) for r in range(rr0,rr1+1) for c in range(cc0,cc1+1) if V[r-rr0,c-cc0]))
            dfs(0,[],0,set())
            if best: sols.append((names_[comb[0]],[f"{n}{dr}{dc}" for n,(dr,dc) in zip(comb,[0]*0)]))
    return sols,M,mr,mc,oset
