G=load()
def f(I):
    I=np.array(I); H,W=I.shape
    cnt=Counter(I.flatten()); bgc=max(cnt,key=lambda c:cnt[c]); nl={c:n for c,n in cnt.items() if c!=bgc}
    linec=max(nl,key=lambda c:nl[c]); objc=min(nl,key=lambda c:nl[c])
    rs=[sum(c==linec for c in r) for r in I]; cs=[sum(I[r][c]==linec for r in range(H)) for c in range(W)]
    mr,mc=rs.index(max(rs)),cs.index(max(cs))
    S=sorted([(r,c) for r in range(H) for c in range(W) if I[r,c]==objc])
    Ts=[lambda r,c:(r,c),lambda r,c:(2*mr-r,c),lambda r,c:(r,2*mc-c),lambda r,c:(2*mr-r,2*mc-c)]
    out=np.full((H,W),bgc,dtype=int)
    for T in Ts:
        for r,c in S:
            rr,cc=T(r,c)
            if 0<=rr<H and 0<=cc<W: out[rr,cc]=linec
    while len(out)>1 and np.all(out[-1]==bgc): out=out[:-1]
    while len(out[0])>1 and np.all(out[:, -1]==bgc): out=out[:,:-1]
    return out.tolist()
for i in range(1,9):
